-- =====================================================================
-- desifaces #eip9
-- Global Face geography + Audio locale normalization
--
-- CONTRACT:
--   * existing tables only
--   * no persistent table creation
--   * preserve legacy Face region codes
--   * normalize Face geography using ISO 3166
--   * neutralize geography-derived stereotypes
--   * normalize TTS country_code / user selectability
--   * idempotent data behavior
--
-- ISO generation source: debian-iso-codes
-- countries: 249
-- subdivisions: 5123
-- =====================================================================

BEGIN;

-- ---------------------------------------------------------------------
-- 1. FACE GEOGRAPHY SCHEMA
-- ---------------------------------------------------------------------

ALTER TABLE public.face_generation_regions
    ADD COLUMN IF NOT EXISTS country_code text NULL,
    ADD COLUMN IF NOT EXISTS subdivision_code text NULL,
    ADD COLUMN IF NOT EXISTS geography_type text NULL;

COMMENT ON COLUMN public.face_generation_regions.country_code IS
    'ISO 3166-1 alpha-2 country code for geography-aware Face masterdata';

COMMENT ON COLUMN public.face_generation_regions.subdivision_code IS
    'ISO 3166-2 subdivision code; NULL for country/profile rows';

COMMENT ON COLUMN public.face_generation_regions.geography_type IS
    'Masterdata geography role: country, subdivision, or profile';


-- ---------------------------------------------------------------------
-- 2. NORMALIZE LEGACY INDIA FACE ROWS
-- ---------------------------------------------------------------------

DO $$
DECLARE
    v_rows bigint;
    v_changes bigint := 0;
BEGIN
    ALTER TABLE public.face_generation_regions
        DISABLE TRIGGER trg_face_generation_regions_bump;

    UPDATE public.face_generation_regions r
       SET country_code = 'IN',
           subdivision_code = m.subdivision_code,
           geography_type = 'subdivision',
           ethnicity_notes = NULL,
           typical_skin_tones = NULL,
           traditional_attire = NULL,
           cultural_markers =
               coalesce(r.cultural_markers, '{}'::jsonb)
               || '{"geography_only":true,"legacy_normalized":true}'::jsonb,
           prompt_base =
               'Geographic context: '
               || coalesce(r.display_name->>'en', r.code)
               || ', India. Represent people and settings naturally and '
               || 'contemporarily. Do not infer facial anatomy, ethnicity, '
               || 'skin tone, religion, attire, occupation, or socioeconomic '
               || 'traits from geography alone.'
      FROM (
          VALUES
            ('andhra_pradesh','IN-AP'),
            ('assam','IN-AS'),
            ('bengal','IN-WB'),
            ('bihar','IN-BR'),
            ('chhattisgarh','IN-CT'),
            ('delhi_ncr','IN-DL'),
            ('goa','IN-GA'),
            ('gujarat','IN-GJ'),
            ('haryana','IN-HR'),
            ('himachal','IN-HP'),
            ('jharkhand','IN-JH'),
            ('karnataka','IN-KA'),
            ('kerala','IN-KL'),
            ('madhya_pradesh','IN-MP'),
            ('maharashtra','IN-MH'),
            ('manipur','IN-MN'),
            ('meghalaya','IN-ML'),
            ('mizoram','IN-MZ'),
            ('nagaland','IN-NL'),
            ('odisha','IN-OR'),
            ('punjab','IN-PB'),
            ('rajasthan','IN-RJ'),
            ('tamil_nadu','IN-TN'),
            ('telangana','IN-TG'),
            ('uttarakhand','IN-UT'),
            ('uttar_pradesh','IN-UP')
      ) AS m(code, subdivision_code)
     WHERE r.code = m.code
       AND (
            r.country_code IS DISTINCT FROM 'IN'
         OR r.subdivision_code IS DISTINCT FROM m.subdivision_code
         OR r.geography_type IS DISTINCT FROM 'subdivision'
         OR r.ethnicity_notes IS NOT NULL
         OR r.typical_skin_tones IS NOT NULL
         OR r.traditional_attire IS NOT NULL
         OR r.cultural_markers IS NULL
         OR NOT coalesce(
                (r.cultural_markers->>'geography_only')::boolean,
                false
             )
         OR r.prompt_base !~ '^Geographic context:'
       );

    GET DIAGNOSTICS v_rows = ROW_COUNT;
    v_changes := v_changes + v_rows;


    UPDATE public.face_generation_regions
       SET country_code = 'IN',
           subdivision_code = NULL,
           geography_type = 'profile',
           ethnicity_notes = NULL,
           typical_skin_tones = NULL,
           prompt_base =
             'Contemporary India profile. Geography may inform setting only. '
             || 'Do not infer facial anatomy, ethnicity, skin tone, religion, '
             || 'attire, occupation, or socioeconomic traits.'
