    )
    INSERT INTO public.face_generation_regions (
        code,
        display_name,
        sub_region,
        ethnicity_notes,
        typical_skin_tones,
        traditional_attire,
        cultural_markers,
        prompt_base,
        is_active,
        sort_order,
        country_code,
        subdivision_code,
        geography_type
    )
    SELECT
        i.code,
        i.display_name,
        NULL,
        NULL,
        NULL,
        NULL,
        '{"geography_only":true,"source":"ISO-3166"}'::jsonb,
        i.prompt_base,
        false,
        i.sort_order,
        i.country_code,
        i.subdivision_code,
        i.geography_type
    FROM incoming i
    WHERE NOT EXISTS (
        SELECT 1
        FROM public.face_generation_regions e
        WHERE e.code = i.code
           OR (
                i.geography_type = 'country'
                AND e.geography_type = 'country'
                AND e.country_code = i.country_code
           )
           OR (
                i.geography_type = 'subdivision'
                AND e.subdivision_code = i.subdivision_code
           )
    )
    ON CONFLICT (code) DO NOTHING;

    GET DIAGNOSTICS v_rows = ROW_COUNT;
    v_changes := v_changes + v_rows;


    ALTER TABLE public.face_generation_regions
        ENABLE TRIGGER trg_face_generation_regions_bump;

    IF v_changes > 0 THEN
        PERFORM public.bump_masterdata_revision('face');
    END IF;
END
$$;


-- ---------------------------------------------------------------------
-- 4. FACE GEOGRAPHY INDEXES
-- ---------------------------------------------------------------------

CREATE INDEX IF NOT EXISTS idx_face_regions_country
    ON public.face_generation_regions(
        country_code,
        geography_type,
        is_active
    );

CREATE INDEX IF NOT EXISTS idx_face_regions_subdivision
    ON public.face_generation_regions(
        country_code,
        subdivision_code
    );

CREATE UNIQUE INDEX IF NOT EXISTS ux_face_regions_country_master
    ON public.face_generation_regions(country_code)
    WHERE geography_type = 'country'
      AND country_code IS NOT NULL;

CREATE UNIQUE INDEX IF NOT EXISTS ux_face_regions_subdivision
    ON public.face_generation_regions(subdivision_code)
    WHERE subdivision_code IS NOT NULL;


-- ---------------------------------------------------------------------
-- 5. FACE GEOGRAPHY CONSTRAINTS
-- ---------------------------------------------------------------------

DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM pg_constraint
        WHERE conname = 'ck_face_regions_country_code'
          AND conrelid = 'public.face_generation_regions'::regclass
    ) THEN
        ALTER TABLE public.face_generation_regions
        ADD CONSTRAINT ck_face_regions_country_code
        CHECK (
            country_code IS NULL
            OR country_code ~ '^[A-Z]{2}$'
        );
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM pg_constraint
        WHERE conname = 'ck_face_regions_subdivision_code'
          AND conrelid = 'public.face_generation_regions'::regclass
    ) THEN
        ALTER TABLE public.face_generation_regions
        ADD CONSTRAINT ck_face_regions_subdivision_code
        CHECK (
            subdivision_code IS NULL
            OR subdivision_code ~ '^[A-Z]{2}-.+'
        );
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM pg_constraint
        WHERE conname = 'ck_face_regions_geography_type'
          AND conrelid = 'public.face_generation_regions'::regclass
    ) THEN
        ALTER TABLE public.face_generation_regions
        ADD CONSTRAINT ck_face_regions_geography_type
        CHECK (
            geography_type IS NULL
            OR geography_type IN ('country','subdivision','profile')
        );
    END IF;


    IF NOT EXISTS (
        SELECT 1
        FROM pg_constraint
        WHERE conname = 'ck_face_regions_subdivision_country'
          AND conrelid = 'public.face_generation_regions'::regclass
    ) THEN
        ALTER TABLE public.face_generation_regions
        ADD CONSTRAINT ck_face_regions_subdivision_country
        CHECK (
            subdivision_code IS NULL
            OR (
                country_code IS NOT NULL
                AND split_part(subdivision_code, '-', 1) = country_code
            )
        );
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM pg_constraint
        WHERE conname = 'ck_face_regions_geography_shape'
          AND conrelid = 'public.face_generation_regions'::regclass
    ) THEN
        ALTER TABLE public.face_generation_regions
        ADD CONSTRAINT ck_face_regions_geography_shape
        CHECK (
            geography_type IS NULL
            OR geography_type = 'profile'
            OR (
                geography_type = 'country'
                AND country_code IS NOT NULL
                AND subdivision_code IS NULL
            )
            OR (
                geography_type = 'subdivision'
                AND country_code IS NOT NULL
                AND subdivision_code IS NOT NULL
            )
        );
    END IF;
END
$$;


-- ---------------------------------------------------------------------
-- 6. AUDIO COUNTRY NORMALIZATION
-- ---------------------------------------------------------------------

DO $$
DECLARE
    v_rows bigint;
    v_changes bigint := 0;
BEGIN
    ALTER TABLE public.tts_locales
        DISABLE TRIGGER trg_tts_mdrev_tts_locales;


    -- Known BCP-47 variants where the region is not the final subtag.
    UPDATE public.tts_locales
       SET region_code = 'CN'
     WHERE locale LIKE 'zh-CN-%'
       AND region_code IS DISTINCT FROM 'CN';

    GET DIAGNOSTICS v_rows = ROW_COUNT;
    v_changes := v_changes + v_rows;


    -- ISO2 BCP-47 region is also the country for these locale rows.
    UPDATE public.tts_locales
       SET country_code = upper(region_code)
     WHERE region_code ~ '^[A-Z]{2}$'
       AND country_code IS DISTINCT FROM upper(region_code);

    GET DIAGNOSTICS v_rows = ROW_COUNT;
    v_changes := v_changes + v_rows;


    -- Known catalog display-name defects.
    UPDATE public.tts_locales l
       SET display_name = x.display_name
      FROM (
          VALUES
            ('pt-PT','Portuguese (Portugal)'),
            ('jv-ID','Javanese (Indonesia)'),
            ('mn-MN','Mongolian (Mongolia)'),
            ('sr-Latn-RS','Serbian (Latin, Serbia)'),
            ('sr-RS','Serbian (Serbia)'),
            ('su-ID','Sundanese (Indonesia)'),
            ('wuu-CN','Wu Chinese (China)'),
            ('zh-CN','Chinese (China)'),
            ('zh-HK','Chinese (Hong Kong)'),
            ('zh-TW','Chinese (Taiwan)'),
            ('zh-CN-henan','Chinese (Henan, China)'),
            ('zh-CN-liaoning','Chinese (Liaoning, China)'),
            ('zh-CN-shaanxi','Chinese (Shaanxi, China)'),
            ('zh-CN-shandong','Chinese (Shandong, China)'),
            ('zh-CN-sichuan','Chinese (Sichuan, China)')
      ) AS x(locale, display_name)
     WHERE l.locale = x.locale
       AND l.display_name IS DISTINCT FROM x.display_name;

    GET DIAGNOSTICS v_rows = ROW_COUNT;
    v_changes := v_changes + v_rows;


    -- Mobile source is English. A target is user-selectable only when
    -- the locale is actually synthesizable and, for non-English
    -- targets, translation support exists.
    UPDATE public.tts_locales
       SET is_user_selectable = (
           is_enabled
           AND tts_supported
           AND country_code ~ '^[A-Z]{2}$'
           AND (
               lower(language_code) = 'en'
               OR translate_supported
           )
       )
     WHERE is_user_selectable IS DISTINCT FROM (
           is_enabled
           AND tts_supported
           AND country_code ~ '^[A-Z]{2}$'
           AND (
               lower(language_code) = 'en'
               OR translate_supported
           )
       );

    GET DIAGNOSTICS v_rows = ROW_COUNT;
    v_changes := v_changes + v_rows;


    ALTER TABLE public.tts_locales
        ENABLE TRIGGER trg_tts_mdrev_tts_locales;

    IF v_changes > 0 THEN
        PERFORM public.bump_masterdata_revision('tts');
    END IF;
END
$$;


-- ---------------------------------------------------------------------
-- 7. AUDIO COUNTRY CONSTRAINT
-- ---------------------------------------------------------------------

DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM pg_constraint
        WHERE conname = 'ck_tts_locales_country_code_iso2'
          AND conrelid = 'public.tts_locales'::regclass
    ) THEN
        ALTER TABLE public.tts_locales
        ADD CONSTRAINT ck_tts_locales_country_code_iso2
        CHECK (
            country_code IS NULL
            OR country_code ~ '^[A-Z]{2}$'
        );
    END IF;
END
$$;

COMMIT;
